import{_ as i,l as p,o as a,c as o,v as t,p as d,x as r,d as s,i as l,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"网桥与 tun / tap","description":"","frontmatter":{"title":"网桥与 tun / tap","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bridge-tun-tap.md","filePath":"cs/bridge-tun-tap.md","lastUpdated":1789023840000}'),u={name:"cs/bridge-tun-tap.md"};function h(_,e,f,b,A,m){const n=p("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="网桥与-tun-tap" tabindex="-1">网桥与 tun / tap <a class="header-anchor" href="#网桥与-tun-tap" aria-label="Permalink to &quot;网桥与 tun / tap&quot;">​</a></h1><div class="epigraph"><p>网桥按 MAC 学习转发，把若干 net_device 收成一台虚拟交换机；tun 交 IP 包、tap 交以太网帧给用户态 fd。</p><footer>—— 据 IEEE 802.1D 学习桥直觉；Linux bridge 与 tuntap 文档</footer></div><p><a href="/cs/netns-veth">上一课</a>的 veth 要接到「交换机」才好多容器互通。缺口是 <strong>bridge</strong> 与 <strong>tun/tap</strong>：一个在内核转二层，一个把帧交给 qemu/VPN 用户态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>桥：端口加入 <code>br0</code>，学 MAC 表，未知单播泛洪，STP 可选防环。与物理交换机同构，对象是 skb。tun：用户 <code>read</code>/<code>write</code> <code>/dev/net/tun</code> 得 IP 包（三层 VPN）；tap 带以太网头（虚拟机网卡）。缺口：桥接 tap 与 veth、VLAN 过滤、以及 <a href="/cs/napi">NAPI</a> 在软件设备上的 <code>netif</code> 调用仍走同一 RX。本课不把 OVS 的流表写成另一门课。</p><p><span class="marginnote">MACVLAN 可避免桥的部分开销。本课以经典桥+tap 讲清对象。GRO 在软件设备上也可挂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>ip link add br0 type bridge</code>，把 veth 与 tap 设为 port。VM 写 tap → 内核 tap 驱动建 skb → 桥转发 → 另一端口 TX。对照 <a href="/cs/device-mapper-lvm">device mapper</a>：dm remap 块号；桥 remap 的是「出哪口」。对照 <a href="/cs/fuse">FUSE</a>：tun 是字符设备把包送用户，不是文件树。</p>',8)),(a(),d(c,null,{default:r(()=>[l(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAP%5B%22tap%20fd%20%E7%94%A8%E6%88%B7%E6%80%81%22%5D%20--%3E%20SKB%5B%22sk_buff%22%5D%0A%20%20VETH%5B%22veth%22%5D%20--%3E%20SKB%0A%20%20SKB%20--%3E%20BR%5B%22%E6%A1%A5%20MAC%20%E5%AD%A6%E4%B9%A0%22%5D%0A%20%20BR%20--%3E%20PORT%5B%22%E5%87%BA%E7%AB%AF%E5%8F%A3%20TX%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>桥把 netns 里的多条虚线收成二层域；tun/tap 把「网卡」的另一头接到进程，这是虚拟机与 VPN 的 OS 接头。不要写成数据中心 fabric。与 netfilter：<code>br_netfilter</code> 可把桥转发再送进 iptables，性能与语义都坑，课序只要求知道钩可以叠。</p><p>隔离：VLAN 过滤与独立 netns 是不同层。</p><p>实现上：桥的 MAC 表老化后未知单播泛洪，容器网络会变成小广播域。tun 无以太网头，VPN 自己封装；tap 给虚拟机当网卡。br_netfilter 让桥包再进 iptables， entangle 二层与三层。 读法上只引用<a href="/cs/netns-veth">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>网桥与 tun / tap</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ebtables 的全部匹配。不保证无线桥接的 WDS 细节。下一课在驱动更早处处理包：XDP 与 eBPF 网络。</p><p>版本字段会变，课序钉的是机制对象「网桥与 tun / tap」，不是某一主线内核的结构体名。 后课默认：软件桥学 MAC；tun/tap 把帧交给用户。XDP 在 NAPI 前可编程收包，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>桥是内核虚拟交换机；tun/tap 是用户态包 fd。</li><li>容器与 VM 网络常靠 veth/tap+桥。</li><li>XDP/eBPF 是下一课。</li><li>出处：Linux bridge；<code>tuntap(4)</code>；802.1D 直觉。</li></ul>',11))])}const E=i(u,[["render",h]]);export{T as __pageData,E as default};
